 "content": "import time

import structlog
from flask import Blueprint, jsonify, request

from ..billing.refunds import refund
from .errors import problem
from .invoices import _INVOICES

bp = Blueprint("refunds", __name__)
log = structlog.get_logger()

APPROVAL_THRESHOLD_CENTS = 50_000
IDEMPOTENCY_TTL_SECONDS = 24 * 60 * 60

# (invoice_id, idempotency key) -> (stored_at, body, status)
_REPLAYS = {}


def _money(cents, currency="USD"):
    return {"minor": cents, "ccy": currency}


@bp.post("/invoices/<invoice_id>/refunds")
def create_refund(invoice_id):
    key = request.headers.get("X-Acme-Idempotency")
    if not key:
        return problem(428, "Idempotency header required", "Send X-Acme-Idempotency.")

    stored = _REPLAYS.get((invoice_id, key))
    if stored and time.time() - stored[0] < IDEMPOTENCY_TTL_SECONDS:
        return jsonify(stored[1]), stored[2]

    actor_id = request.headers.get("X-Actor-Id")
    if not actor_id:
        return problem(401, "Actor required", "Send X-Actor-Id.")

    invoice = _INVOICES.get(invoice_id)
    if invoice is None:
        return problem(404, "Invoice not found")

    payload = request.get_json(silent=True) or {}
    amount = payload.get("amount_cents")
    if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
        return problem(422, "Invalid amount", "amount_cents must be a positive integer.")

    if amount > invoice.subtotal_cents + invoice.tax_cents:
        return problem(422, "Refund exceeds invoice total")

    if amount > APPROVAL_THRESHOLD_CENTS:
        # Large refunds need a second approver; do not issue directly.
        status = "pending_approval"
        result = None
    else:
        status = "issued"
        try:
            result = refund(invoice, amount)
        except ValueError as exc:
            return problem(422, "Refund rejected", str(exc))
        log.info(
            "ledger.refund_issued",
            invoice_id=invoice.id,
            customer_id=invoice.customer_id,
            amount_cents=amount,
            actor_id=actor_id,
        )

    body = {
        "invoice_id": invoice.id,
        "status": status,
        "refunded": _money(result["refunded_cents"]) if result else None,
        "requested": _money(amount),
    }
    _REPLAYS[(invoice_id, key)] = (time.time(), body, 201)
    return jsonify(body), 201
"
}

